using System;using System.Linq;using BeamScheduleFormatter;
class CurtailmentTests{static int checks;static void Near(double a,double b){if(Math.Abs(a-b)>1e-8)throw new Exception("Curtailment length mismatch "+a+" != "+b);checks++;}static BeamRow Row(int l,int m,int r){var b=new BeamRow{Mark="T-001",Leg="2L",Diameter="%%C10",RevisedSpacing="1 - 50mm, AND REST AT 200mm C/C"};b.Cells[0].Add("450");b.Cells[1].Add("800");int[] counts={l,m,r};for(int f=0;f<2;f++)for(int z=0;z<3;z++)b.Cells[2+f*3+z].Add(counts[z]+"-%%C20");return b;}static void Main(){var a=EstimatorEngine.Calculate(Row(2,4,2),"T",12,new EstimateOptions());Near(a.Lines.Single(x=>x.Part=="Bottom CUT MIDSPAN").CutLength,8);Near(a.Lines.Single(x=>x.Part=="Top CUT MIDSPAN").CutLength,6);Near(a.Lines.Single(x=>x.Part=="Bottom CONTINUOUS").Metres,24);var b=EstimatorEngine.Calculate(Row(4,4,2),"T",12,new EstimateOptions());Near(b.Lines.Single(x=>x.Part=="Bottom CUT LEFT+MIDSPAN").CutLength,10);Near(b.Lines.Single(x=>x.Part=="Top CUT LEFT+MIDSPAN").CutLength,9);var c=EstimatorEngine.Calculate(Row(4,2,4),"T",12,new EstimateOptions());foreach(var p in c.Lines.Where(x=>x.Part.Contains("CUT")))Near(p.CutLength,3);var d=EstimatorEngine.Calculate(Row(4,4,4),"T",12,new EstimateOptions());Near(d.Lines.Count(x=>x.Part.Contains("CONTINUOUS")),2);Near(d.Lines.Count(x=>x.Part.Contains("CUT")),0);Console.WriteLine("PASS: "+checks+" fixed screenshot curtailment cases/checks; bottom midspan2L/3, top middleL/2, supportL/4, adjacent unions and continuous full length.");}}
